(ROOT/'shortlist-10.json').write_text(json.dumps([{'id':x['id'],'name':x['name'],'overall_rank':x['rank'],'score':x['final_score'],'proposed_monthly_usd':x['pricing']['monthly_usd'],'accounts_to_5000_mrr':x['accounts_to_5000_mrr']} for x in short],indent=2)+'\n')
